(function(){"use strict";function initElement(el){if(el._danLlTimer){clearInterval(el._danLlTimer)}var interval=parseInt(el.getAttribute("data-interval"),10)||2500;var stagger=parseFloat(el.getAttribute("data-stagger"))||0.13;var groups=Array.from(el.querySelectorAll(".dan-looping-logos__group"));var total=groups.length;if(total===0){return}var currentIndex=0;groups.forEach(function(group){Array.from(group.querySelectorAll(".dan-looping-logos__item")).forEach(function(item,index){item.style.transitionDelay=index*stagger+"s"})});groups[0].classList.add("dan-looping-logos__group--visible");if(total<=1){return}el._danLlTimer=setInterval(function(){var prevIndex=currentIndex;currentIndex=(currentIndex+1)%total;var exitGroup=groups[prevIndex];var enterGroup=groups[currentIndex];var exitItems=Array.from(exitGroup.querySelectorAll(".dan-looping-logos__item"));exitItems.forEach(function(item,index){item.style.transitionDelay=index*stagger*0.77+"s"});exitGroup.classList.remove("dan-looping-logos__group--visible");exitGroup.classList.add("dan-looping-logos__group--exiting");var enterItems=Array.from(enterGroup.querySelectorAll(".dan-looping-logos__item"));enterItems.forEach(function(item){item.style.transition="none"});void enterGroup.offsetWidth;enterItems.forEach(function(item,index){item.style.transition="";item.style.transitionDelay=index*stagger+"s"});enterGroup.classList.add("dan-looping-logos__group--visible");var exitDuration=((exitItems.length-1)*stagger*0.77+0.6)*1000;setTimeout(function(){exitGroup.classList.remove("dan-looping-logos__group--exiting");exitItems.forEach(function(item){item.style.transition="none"});void exitGroup.offsetWidth;exitItems.forEach(function(item,index){item.style.transition="";item.style.transitionDelay=index*stagger+"s"})},exitDuration)},interval)}function initAll(){document.querySelectorAll(".dan-looping-logos").forEach(function(el){el.removeAttribute("data-flickering");initElement(el)})}window.dancepad_looping_logos=initAll;if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",initAll)}else{initAll()}})();
